 private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private int color(String c){return Color.parseColor(c);}
 private void palette(){String mode=prefs.getString("theme","system");dark=mode.equals("dark")||(mode.equals("system")&&(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);bg=color(dark?"#0B1420":"#F4F6FA");card=color(dark?"#152235":"#FFFFFF");ink=color(dark?"#EDF3FC":"#172B45");muted=color(dark?"#91A3BD":"#5E7088");line=color(dark?"#26364B":"#E6EBF2");accent=color(dark?"#79D7C0":"#117C70");}
 private GradientDrawable shape(int c,int radius){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(radius));return g;}
 private TextView text(String value,int size,int c,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(c);t.setFontFeatureSettings("tnum");t.setTypeface(Typeface.create(bold?"sans-serif-medium":"sans-serif",Typeface.NORMAL));return t;}
 private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
