 private TextView button(String value,int fill,int fg,Runnable action){TextView v=text(value,15,fg,true);v.setGravity(Gravity.CENTER);v.setMinHeight(dp(50));v.setBackground(shape(fill,16));v.setOnClickListener(x->action.run());v.setFocusable(true);return v;}
