 private void section(String title,String action,Runnable click){LinearLayout r=row();r.setPadding(dp(2),dp(10),dp(2),dp(10));r.addView(text(title,17,ink,true),new LinearLayout.LayoutParams(0,-2,1));TextView a=text(action,12,accent,true);a.setPadding(dp(12),dp(9),0,dp(9));a.setOnClickListener(v->click.run());r.addView(a);body.addView(r);}
 private void nodes(){
  section("我的节点",book.nodes().size()+" 个",()->{});if(book.nodes().isEmpty()){LinearLayout e=panel();gap(e,30);TextView icon=text("＋",42,accent,false);icon.setGravity(Gravity.CENTER);e.addView(icon);TextView t=text("你的节点，从这里开始",19,ink,true);t.setGravity(Gravity.CENTER);e.addView(t);gap(e,12);TextView note=text("添加不同 VPS，按需要选择和切换。",13,muted,false);note.setGravity(Gravity.CENTER);e.addView(note);gap(e,28);e.addView(button("添加节点",accent,dark?color("#102821"):Color.WHITE,()->editNode(null)));addPanel(body,e);return;}
  int i=1;for(NodeBook.Node n:book.nodes())addPanel(body,nodeCard(n,i++,true));gap(body,8);body.addView(button("＋ 添加另一个节点",dark?color("#1B2F36"):color("#E5EEE9"),accent,()->editNode(null)));gap(body,16);body.addView(text("选中节点后，前往连接页即可连接。切换正在使用的节点会重新建立 VPN。",12,muted,false));
 }
 private LinearLayout nodeCard(NodeBook.Node n,int index,boolean menu){
  LinearLayout outer=panel(),r=row();boolean selected=book.selected()!=null&&book.selected().id.equals(n.id);if(selected){GradientDrawable border=shape(card,22);border.setStroke(dp(1),accent);outer.setBackground(border);}
  TextView badge=text(index>0?String.format(Locale.ROOT,"%02d",index):"m",18,accent,true);badge.setGravity(Gravity.CENTER);badge.setBackground(shape(dark?color("#253E3A"):color("#EDF4EF"),14));r.addView(badge,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout labels=vertical();labels.setPadding(dp(13),0,dp(4),0);TextView name=text(n.name,16,ink,true);name.setSingleLine();name.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(name);gap(labels,5);TextView host=text(n.address(),12,muted,false);host.setSingleLine();host.setEllipsize(android.text.TextUtils.TruncateAt.MIDDLE);labels.addView(host);r.addView(labels,new LinearLayout.LayoutParams(0,-2,1));
  if(menu){TextView more=text("⋮",25,muted,true);more.setGravity(Gravity.CENTER);more.setContentDescription("管理节点 "+n.name);r.addView(more,new LinearLayout.LayoutParams(dp(48),dp(48)));more.setOnClickListener(v->nodeMenu(n,more));}else{TextView edit=text("编辑",12,accent,true);edit.setPadding(dp(10),dp(12),0,dp(12));edit.setMinHeight(dp(48));edit.setMinWidth(dp(48));r.addView(edit);edit.setOnClickListener(v->editNode(n));}outer.addView(r);if(menu){gap(outer,13);LinearLayout footer=row();String s=MioVpnService.running&&n.id.equals(prefs.getString("active_id",""))?"● 使用中":selected?"● 已选择":"○ 点击选择";TextView nodeStatus=text(s,11,selected?accent:muted,true);nodeStates.put(n.id,nodeStatus);footer.addView(nodeStatus,new LinearLayout.LayoutParams(0,-2,1));footer.addView(text("mio · TCP / QUIC",10,muted,false));outer.addView(footer);}if(menu)outer.setOnClickListener(v->{book.select(n.id);if(persist()){toast("已选择 "+n.name);render();}});return outer;
 }
 private void nodeMenu(NodeBook.Node n,View anchor){PopupMenu m=new PopupMenu(this,anchor);m.getMenu().add("编辑节点");m.getMenu().add("复制节点");m.getMenu().add("删除节点");m.setOnMenuItemClickListener(item->{String s=item.getTitle().toString();if(s.equals("编辑节点"))editNode(n);else if(s.equals("复制节点")){String name=n.name.substring(0,Math.min(57,n.name.length()))+" 副本";book.put(NodeBook.Node.create(name,n.server,n.port,n.dest,n.destPort,n.password));if(persist())render();}else deleteNode(n);return true;});m.show();}
 private void deleteNode(NodeBook.Node n){if(MioVpnService.running&&n.id.equals(prefs.getString("active_id",""))){toast("请先断开正在使用的节点");return;}new AlertDialog.Builder(this).setTitle("删除“"+n.name+"”？").setMessage("只删除手机上的节点配置，不会更改 VPS。").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{book.remove(n.id);if(persist())render();}).show();}
 private EditText field(LinearLayout box,String label,String value,int type){box.addView(text(label,12,muted,true));gap(box,7);EditText e=new EditText(this);e.setTextSize(15);e.setTextColor(ink);e.setHintTextColor(muted);e.setSingleLine();e.setInputType(type);e.setText(value);e.setPadding(dp(14),dp(12),dp(14),dp(12));GradientDrawable g=shape(bg,12);g.setStroke(dp(1),line);e.setBackground(g);box.addView(e,new LinearLayout.LayoutParams(-1,dp(48)));gap(box,16);return e;}
 private void editNode(NodeBook.Node existing){
  Dialog dialog=new Dialog(this);LinearLayout content=vertical();content.setPadding(dp(24),dp(22),dp(24),dp(18));content.setBackground(shape(card,26));LinearLayout heading=row();heading.addView(text(existing==null?"添加节点":"编辑节点",23,ink,true),new LinearLayout.LayoutParams(0,-2,1));TextView close=text("×",28,muted,false);close.setPadding(dp(12),0,0,0);close.setMinHeight(dp(48));close.setMinWidth(dp(48));close.setOnClickListener(v->dialog.dismiss());heading.addView(close);content.addView(heading);gap(content,18);ScrollView scroll=new ScrollView(this);LinearLayout fields=vertical();scroll.addView(fields);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));int normal=InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS;
  EditText name=field(fields,"节点名称",existing==null?"":existing.name,normal);name.setHint("例如：新加坡 · 日常");EditText server=field(fields,"服务器 IP 或域名",existing==null?"":existing.server,normal);server.setHint("例如：203.0.113.10");EditText port=field(fields,"连接端口",existing==null?"8443":String.valueOf(existing.port),InputType.TYPE_CLASS_NUMBER);EditText password=field(fields,"连接密码",existing==null?"":existing.password,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setTransformationMethod(PasswordTransformationMethod.getInstance());CheckBox show=new CheckBox(this);show.setText("显示密码");show.setTextColor(muted);show.setTextSize(12);fields.addView(show);show.setOnCheckedChangeListener((b,checked)->{password.setTransformationMethod(checked?null:PasswordTransformationMethod.getInstance());password.setSelection(password.length());});gap(fields,12);EditText dest=field(fields,"伪装域名",existing==null?"one.one.one.one":existing.dest,normal);EditText destPort=field(fields,"伪装站端口",existing==null?"443":String.valueOf(existing.destPort),InputType.TYPE_CLASS_NUMBER);fields.addView(text("伪装域名、端口和密码需要与服务端一致。",12,muted,false));gap(fields,16);TextView error=text("",12,color("#D36C60"),false);content.addView(error);gap(content,8);
  content.addView(button("保存节点",accent,dark?color("#102821"):Color.WHITE,()->{try{NodeBook.Node n=NodeBook.Node.create(name.getText().toString(),server.getText().toString(),Integer.parseInt(port.getText().toString()),dest.getText().toString(),Integer.parseInt(destPort.getText().toString()),password.getText().toString());if(existing!=null){n.id=existing.id;n.revision=Math.max(System.currentTimeMillis(),existing.revision+1);}n.validate();NodeBook next=NodeBook.decode(book.encode());next.put(n);if(existing==null)next.select(n.id);store.save(next);book=next;dialog.dismiss();render();toast(existing==null?"节点已添加":"节点已保存");}catch(NumberFormatException e){error.setText("请输入有效的端口数字");}catch(Exception e){error.setText(e.getMessage());}}));dialog.setContentView(content);Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);w.setGravity(Gravity.BOTTOM);}dialog.show();if(w!=null)w.setLayout(-1,(int)(getResources().getDisplayMetrics().heightPixels*.88f));
 }
 private boolean persist(){try{store.save(book);return true;}catch(Exception e){toast("保存失败："+e.getMessage());try{book=store.load();}catch(Exception ignored){}return false;}}
 private boolean currentMatches(){NodeBook.Node n=book.selected();return n!=null&&n.id.equals(prefs.getString("active_id",""))&&n.revision==prefs.getLong("active_revision",0);}
 private void mainAction(){
  if(startRequested)return;NodeBook.Node n=book.selected();if(n==null){editNode(null);return;}
  if(MioVpnService.running&&currentMatches()){startService(new Intent(this,MioVpnService.class).setAction("STOP"));updateStatus();return;}
  pendingId=n.id;pendingRevision=n.revision;startRequested=true;Intent permission=VpnService.prepare(this);if(permission!=null)startActivityForResult(permission,1);else startSelected();
 }
 private void startSelected(){
  handler.removeCallbacks(startRetry);NodeBook.Node n=book.get(pendingId);
  if(n==null||n.revision!=pendingRevision){startRequested=false;toast("节点已更改，请重新连接");return;}
  if(MioVpnService.running){startService(new Intent(this,MioVpnService.class).setAction("STOP"));handler.postDelayed(startRetry,400);return;}
  try{Intent i=new Intent(this,MioVpnService.class).setAction("START");i.putExtra("node_id",n.id);startForegroundService(i);}catch(RuntimeException e){toast("无法启动 VPN："+e.getMessage());}finally{startRequested=false;}updateStatus();
 }
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==1&&result==RESULT_OK)startSelected();else if(r==1){startRequested=false;toast("未允许 VPN 连接");}}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
 private void settings(){section("偏好设置","",()->{});LinearLayout a=panel();addSetting(a,"外观",themeName(),()->new AlertDialog.Builder(this).setTitle("外观").setSingleChoiceItems(new String[]{"跟随系统","浅色","深色"},prefs.getString("theme","system").equals("light")?1:prefs.getString("theme","system").equals("dark")?2:0,(d,w)->{prefs.edit().putString("theme",new String[]{"system","light","dark"}[w]).apply();d.dismiss();render();}).setNegativeButton("取消",null).show());addPanel(body,a);LinearLayout tools=panel();addSetting(tools,"运行日志","排查连接问题",()->showLogs());addPanel(body,tools);section("关于连接","",()->{});LinearLayout about=panel();about.addView(text("pre-smio 1.0.3",20,ink,true));gap(about,10);about.addView(text("mio 协议的社区 Android 客户端",13,muted,false));gap(about,16);about.addView(text("• 节点密码使用 Android 密钥库加密保存。\n\n• 代理当前用户中的应用 TCP 流量，DNS 通过 mio 转为 TCP。其他应用 UDP 暂不支持。\n\n• 断开 VPN 后恢复普通网络。本版没有实现断网保护。",13,muted,false));gap(about,16);TextView github=text("查看 mio 协议项目 ↗",13,accent,true);github.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/orgmio/mio"))));about.addView(github);addPanel(body,about);}
 private String themeName(){String t=prefs.getString("theme","system");return t.equals("light")?"浅色":t.equals("dark")?"深色":"跟随系统";}
 private void addSetting(LinearLayout parent,String title,String subtitle,Runnable action){LinearLayout r=row();LinearLayout labels=vertical();labels.addView(text(title,16,ink,true));gap(labels,5);labels.addView(text(subtitle,12,muted,false));r.addView(labels,new LinearLayout.LayoutParams(0,-2,1));r.addView(text("›",26,muted,false));r.setOnClickListener(v->action.run());parent.addView(r);}
 private void showLogs(){Dialog d=new Dialog(this);LinearLayout box=panel();box.addView(text("运行日志",21,ink,true));gap(box,12);ScrollView sc=new ScrollView(this);logText=text("",11,muted,false);logText.setTypeface(Typeface.MONOSPACE);logText.setTextIsSelectable(true);sc.addView(logText);box.addView(sc,new LinearLayout.LayoutParams(-1,0,1));gap(box,12);box.addView(button("复制日志",accent,dark?color("#102821"):Color.WHITE,()->{ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("pre-smio 日志",readLog()));toast("日志已复制，可能包含访问域名");}));gap(box,8);box.addView(button("关闭",bg,ink,()->d.dismiss()));d.setContentView(box);d.setOnDismissListener(v->logText=null);d.show();d.getWindow().setBackgroundDrawableResource(android.R.color.transparent);d.getWindow().setLayout(getResources().getDisplayMetrics().widthPixels-dp(24),(int)(getResources().getDisplayMetrics().heightPixels*.8));logText.setText(readLog());}
 private String readLog(){try{return new String(Files.readAllBytes(new File(getFilesDir(),"core.log").toPath()),StandardCharsets.UTF_8);}catch(Exception e){return "暂无日志";}}
 private boolean showCrashReport(){
  File file=new File(getFilesDir(),"last-crash.txt");if(!file.exists())return false;
  String contents;try{contents=new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);}catch(Exception e){contents="无法读取崩溃记录："+e;}
  final String report=contents;
  LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,32,32,32);box.setBackgroundColor(Color.WHITE);box.setFitsSystemWindows(true);
  TextView title=new TextView(this);title.setText("上次启动发生错误");title.setTextSize(22);title.setTextColor(Color.BLACK);box.addView(title);
  TextView note=new TextView(this);note.setText("节点数据已保留。请复制下面的报告发来，以便定位启动错误。\n");note.setTextColor(Color.DKGRAY);box.addView(note);
  ScrollView scroll=new ScrollView(this);TextView detail=new TextView(this);detail.setText(report);detail.setTextSize(12);detail.setTextColor(Color.DKGRAY);detail.setTypeface(Typeface.MONOSPACE);detail.setTextIsSelectable(true);scroll.addView(detail);box.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  Button copy=new Button(this);copy.setText("复制崩溃报告");copy.setOnClickListener(v->{ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("pre-smio 崩溃报告",report));Toast.makeText(this,"已复制",Toast.LENGTH_SHORT).show();});box.addView(copy);
  Button retry=new Button(this);retry.setText("重试进入应用");retry.setOnClickListener(v->{file.delete();recreate();});box.addView(retry);setContentView(box);return true;
 }
 private void updateStatus(){
  if(book==null)return;if(logText!=null)logText.setText(readLog());boolean running=MioVpnService.running;String phase=running?prefs.getString("phase","starting"):"idle";String error=prefs.getString("error","");boolean verified=running&&phase.equals("connected");
  for(java.util.Map.Entry<String,TextView> entry:nodeStates.entrySet()){NodeBook.Node item=book.get(entry.getKey());if(item==null)continue;boolean used=running&&item.id.equals(prefs.getString("active_id",""));boolean selected=book.selected()!=null&&item.id.equals(book.selected().id);entry.getValue().setText(used?(item.revision==prefs.getLong("active_revision",0)?"● 使用中":"● 修改待重连"):selected?"● 已选择":"○ 点击选择");}
  if(statusText!=null){statusText.setText(verified?"● 已连接":running?(phase.equals("starting")?"◌ 正在连接":"● 连接待验证"):!error.isEmpty()?"● 连接已中断":"○ 未连接");statusText.setTextColor(verified?color("#D9F58A"):color("#B9CADD"));NodeBook.Node n=book.selected();detailText.setText(verified?"连接已就绪":running?(phase.equals("unverified")?"连接尚未验证":phase.equals("ready")?"正在验证连接":"正在建立连接"):!error.isEmpty()?"连接未完成":"准备好连接了吗");hintText.setText(running?(phase.equals("unverified")?"出口检测未通过，可在设置中查看日志":"正在使用："+prefs.getString("active_name","mio")):!error.isEmpty()?error:n!=null?n.name:"连接你选择的节点");detailText.setContentDescription(!error.isEmpty()?error:detailText.getText());actionButton.setText(running?(currentMatches()?"断开连接":"切换并连接"):n==null?"添加节点":"连接");exitText.setText(verified?prefs.getString("exit_ip","—"):"—");long elapsed=running?Math.max(0,(SystemClock.elapsedRealtime()-prefs.getLong("started_elapsed",SystemClock.elapsedRealtime()))/1000):0;timeText.setText(elapsed>=3600?String.format(Locale.ROOT,"%02d:%02d:%02d",elapsed/3600,(elapsed/60)%60,elapsed%60):String.format(Locale.ROOT,"%02d:%02d",elapsed/60,elapsed%60));orbit.connected=verified;orbit.busy=running&&!verified&&!phase.equals("unverified");orbit.invalidate();}
 }
 @Override protected void onResume(){super.onResume();if(book!=null){handler.post(refresh);if(startRequested&&VpnService.prepare(this)==null)handler.post(startRetry);}}
 @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
